const OPENING_UI6={cityView,storesView,roastersView,bakeryView,bind,render,map,help};
function openingReadinessUI6(p){if(p.kind!=='cafe'||p.franchise||p.status==='cancelled')return '';const coffee=cafeCoffeeStatus6(p.location,p.blueprint.blend),live=openingLive6(p),units=live?live.crew.employees.reduce((n,x)=>n+x.contract,0):openingUnits6(p);return `<div class="opening-readiness6"><article><strong>${p.entity?'Kavárna ve zkušebním provozu':OPENING_PHASES6[p.phase]}</strong><small>${p.entity?'Tým i menu již můžeš řídit.':'Příprava '+p.elapsed+' týdnů · plán otevření T'+p.plannedEnd}</small></article><article class="${coffee.attention?'attention':''}"><strong>${esc(coffee.title)}</strong><small>${esc(coffee.text)}</small></article><article><strong>${live?'Zaměstnaný tým':p.hired?'Tým přijatý':'Tým rezervovaný'} · ${units} / ${p.need} období</strong><small>${live?'Otevři správu lidí a směn.':p.hired?'Nábor je zaplacený, mzdy už běží. Po instalaci přejdou lidé do kavárny.':'Můžeš vybrat konkrétní lidi a změnit směny. Nábor a mzdy začnou ve fázi náboru.'}</small></article></div>`;}
function openingCafeSupply6(p){if(typeof gameSupplierDialog6==='function')gameSupplierDialog6(p.location);else{el('modal').close();goto('supply');}}
function openingTeamDialog6(id){
 const p=openingById6(id);if(!p||p.kind!=='cafe'||p.franchise)return;const live=openingLive6(p);if(live){el('modal').close();crewSelected5=live.id;goto('crew');return;}
 const editable=p.status==='active'&&!p.hired,market=editable?[...p.people,...state.baristaCandidates.filter(x=>!academyBusy6(x.pid))]:p.people;
 show(`<h2>Tým přípravy · ${esc(p.name)}</h2><p class="sub">${editable?'Vyber rezervované pracovníky a směny. Uložení je bez platby; nábor se zaplatí při jeho zahájení.':'Tým už nastoupil a pobírá mzdu. Rezervace jsou uzavřené; po instalaci otevři běžnou správu kavárny.'}</p><div class="fields opening-shifts6">${['Ráno','Poledne','Večer'].map((name,i)=>field(name,input('openingTeamShift6-'+i,p.blueprint.shifts[i],0,7))).join('')}</div><div class="opening-team-list6">${market.map(person=>`<label class="checkbox-line opening-person6"><input type="checkbox" data-opening-person6="${person.pid}" ${p.people.some(x=>x.pid===person.pid)?'checked':''} ${editable?'':'disabled'}><span><strong>${esc(person.name)}</strong><small>Úvazek ${person.contract} období/den · obsluha ${round(person.skills.service)} · ${p.people.includes(person)?p.hired?'Zaměstnaný':'Rezervovaný':'Volný kandidát'}</small></span></label>`).join('')}</div><div id="openingTeamPreview6"></div><div class="actions">${editable?'<button class="primary" id="openingTeamSave6">Uložit tým a směny</button>':''}<button class="soft" id="openingTeamBack6">Zpět k přípravě</button></div>`);
 for(let i=0;i<3;i++)el('openingTeamShift6-'+i).disabled=!editable;
 let quote;const read=()=>({shifts:[0,1,2].map(i=>Number(el('openingTeamShift6-'+i).value)),pids:[...el('modalContent').querySelectorAll('[data-opening-person6]:checked')].map(x=>x.dataset.openingPerson6)}),preview=()=>{try{quote=openingTeamQuote6(id,read());el('openingTeamPreview6').innerHTML=rows([['Pokrytí směn',quote.units+' / '+quote.need+' období'],['Pozdější nábor',money(quote.recruitment)],['Mzdy s odvody po náboru / týden',money(quote.payroll)],['Platba nyní','0 Kč']]);el('openingTeamSave6').disabled=false;}catch(e){quote=null;el('openingTeamPreview6').innerHTML='<p class="warning">'+esc(e.message)+'</p>';if(el('openingTeamSave6'))el('openingTeamSave6').disabled=true;}};
 if(editable){el('modalContent').querySelectorAll('input').forEach(x=>x.oninput=preview);preview();el('openingTeamSave6').onclick=()=>{try{setOpeningTeam6(id,read(),quote);persist();render();openingTeamDialog6(id);toast('Rezervovaný tým a směny uloženy.');}catch(e){toast(e.message);}};}el('openingTeamBack6').onclick=()=>openingProjectDialog6(id);
}
function openingRecoveryAction6(p){try{const q=openingStarterRecoveryQuote6(p.id);return `<div class="opening-budget6 attention"><h3>Zmenšit první kavárnu</h3><p>Vrať dražší vybavení a přejdi na startovací prostor se 16 místy. Další přípravu povedeš sám.</p>${rows([['Vrácení do hotovosti',money(q.refund)],['Ztráta při vrácení',money(q.writeoff)],['Hotovost po změně',money(q.after)],['Nový nájem / týden',money(q.rent)]])}<button class="soft" id="openingRecovery6" ${q.after<0?'disabled':''}>Prověřit zmenšení projektu</button><p class="sub">Dosavadní nájmy, mzdy a nábor se nevrací. Tým i dokončené fáze zůstanou. Změna není půjčka ani peníze zdarma.</p></div>`;}catch{return '';}}
function openingRecoveryDialog6(id){try{const q=openingStarterRecoveryQuote6(id);confirmAction('Zmenšit připravovanou kavárnu?',money(q.refund)+' zpět do hotovosti, '+money(q.writeoff)+' odpis. Nájem '+money(q.rent)+'/týden, 16 míst, základní vybavení. Vedoucí se uvolní, přípravu povede zakladatel. Dosavadní mzdy a nábor zůstávají zaplacené.',()=>recoverOpeningStarter6(id,q),'Zmenšit a vrátit vybavení');}catch(e){toast(e.message);}}
function openingCards6(kind=null){const list=state.opening6.projects.filter(p=>(!kind||p.kind===kind)&&(p.status==='active'||p.closed>=state.week-13));return list.length?`<section class="card" style="margin-bottom:24px"><h2>Příprava a otevření provozů</h2><p class="sub">Čas, prostor, lidé a káva se platí. Kliknutím otevřeš plán, skutečné kroky a zpoždění.</p><div class="cards">${list.map(p=>`<article><span class="badge">${esc(p.city)} · ${p.status==='active'?OPENING_PHASES6[p.phase]:p.status==='completed'?'Otevřeno':'Ukončeno'}</span><h3>${esc(p.name)}</h3><p>${p.elapsed} týdnů přípravy · plán T${p.plannedEnd}${p.closed?' · skutečnost T'+p.closed:''}</p>${p.blocked?`<p class="warning">${esc(p.blocked)}</p>`:''}<button class="soft" data-opening-report6="${p.id}">Plán a skutečný výsledek</button></article>`).join('')}</div></section>`:'';}
function openingProjectDialog6(id){const p=openingById6(id);if(!p)return;show(`<span class="eyelabel">PŘÍPRAVA PROVOZU · ${esc(p.city)}</span><h2>${esc(p.name)}</h2>${openingReadinessUI6(p)}${openingRecoveryAction6(p)}${p.kind==='cafe'&&!p.franchise&&(p.status==='active'||openingLive6(p))?`<div class="actions"><button class="soft" id="openingTeamManage6">${p.entity?'Řídit tým a směny':'Tým a směny přípravy'}</button><button class="soft" id="openingSupplyManage6">${cafeCoffeeStatus6(p.location,p.blueprint.blend).action}</button></div>`:''}${rows([['Stav',p.status==='active'?OPENING_PHASES6[p.phase]:p.status==='completed'?'Plný provoz':'Ukončeno'],['Plánovaný termín','T'+p.plannedEnd],['Skutečný postup',p.elapsed+' zaplacených týdnů'],['Zaplacený majetek',money(p.paidCapital)],['Administrativa a vedoucí',money(p.admin+p.managerFee)],['Nábor lidí',money(p.recruitment)],['Prostor, mzdy a odvody před spuštěním',money(p.operating)],['Další zásahy',money(p.extras)],['Rezervovaný tým',p.entity?'Převeden do skutečného provozu':p.people.map(x=>x.name).join(', ')||'Chybí tým']])}${p.blocked?`<p class="warning">${esc(p.blocked)}</p>`:''}<ol>${OPENING_PHASES6.map((name,i)=>`<li>${name} · plán ${p.durations[i]} ${p.durations[i]===1?'týden':'týdny'}${p.phaseHistory.find(x=>x.phase===i)?' · dokončeno T'+p.phaseHistory.find(x=>x.phase===i).finished:''}</li>`).join('')}</ol><p class="sub">Zkušební kavárna má 35 % místní poptávky, výrobna 50 % kapacity. Kompaktní vybavení bez kontroly má při spuštění stav 78 % a potřebuje další týden zkoušky. Tyto podmínky se promítnou do skutečných šarží, zákazníků, nákladů a stavu zařízení.</p>${p.status==='active'&&!p.entity?`<h3>Pravomoci přípravy</h3><p>${esc(p.manager?.name||'Vede zakladatel')} · ${p.manager?MANAGER_STRATEGIES6[openingStyle6(p)].name:'Ruční příprava'}</p><div class="fields">${field('Týdenní limit placených zásahů',input('openingBudget6',p.policy.budget,0,50000,500))}${field('Rezerva · týdny',input('openingReserve6',p.policy.reserve,1,8))}</div><label><input id="openingPersonal6" type="checkbox" ${p.policy.personal?'checked':''}> Povolit osobní strategii vedoucího</label><br><label><input id="openingAccelerate6" type="checkbox" ${p.policy.accelerate?'checked':''}> Povolit urychlení instalace</label><br><label><input id="openingQuality6" type="checkbox" ${p.policy.quality?'checked':''}> Povolit placenou kontrolu kvality</label><div class="actions"><button class="primary" id="openingPolicySave6">Uložit pravomoci</button><button class="soft" id="openingCancel6">Vyúčtovat ukončení přípravy</button></div>${!p.hired&&p.kind!=='roaster'?`<h3>Doplnit rezervaci skutečného pracovníka</h3><select id="openingWorker6">${(p.kind==='cafe'?state.baristaCandidates:state.academy6.bakerCandidates).filter(x=>!academyBusy6(x.pid)).map(x=>option(x.pid,x.name+(x.contract?' · '+x.contract+' období/den':''),null)).join('')}</select><button class="soft" id="openingWorkerAdd6">Rezervovat pracovníka</button>`:''}`:''}<h3>Co se opravdu stalo</h3><div class="table-scroll"><table class="data"><thead><tr><th>Týden a fáze</th><th>Rozhodnutí a důvod</th><th>Platba / výsledek</th></tr></thead><tbody>${p.history.slice().reverse().map(r=>`<tr><td>T${r.week} · ${OPENING_PHASES6[r.phase]}<small>${r.steps} dokončené kroky</small></td><td>${esc(r.author)}<small>${esc(r.action)}</small></td><td>${money(r.operating+r.cost)}<small>${r.trialOutput===null?'Před spuštěním bez tržeb':r.trialProfit!==null?'Zkouška: '+money(r.trialProfit):'Výstup zkoušky: '+number(r.trialOutput)+' '+(p.kind==='roaster'?'kg':'kusů')}</small></td></tr>`).join('')||'<tr><td colspan="3">Příprava zatím neměla skutečný týden.</td></tr>'}</tbody></table></div>`);
 if(el('openingRecovery6'))el('openingRecovery6').onclick=()=>openingRecoveryDialog6(id);if(el('openingTeamManage6'))el('openingTeamManage6').onclick=()=>openingTeamDialog6(id);if(el('openingSupplyManage6'))el('openingSupplyManage6').onclick=()=>openingCafeSupply6(p);
 if(el('openingPolicySave6'))el('openingPolicySave6').onclick=()=>act(()=>setOpeningPolicy6(id,{personal:el('openingPersonal6').checked,accelerate:el('openingAccelerate6').checked,quality:el('openingQuality6').checked,budget:Number(el('openingBudget6').value),reserve:Number(el('openingReserve6').value)}),'Pravomoci přípravy uloženy.');
 if(el('openingWorkerAdd6'))el('openingWorkerAdd6').onclick=()=>{try{addOpeningWorker6(id,el('openingWorker6').value);persist();render();openingProjectDialog6(id);}catch(e){toast(e.message);}};
 if(el('openingCancel6'))el('openingCancel6').onclick=()=>{try{const q=openingCancelQuote6(id);confirmAction('Ukončit přípravu '+esc(p.name)+'?',money(q.refund)+' zpět do hotovosti; '+money(q.writeoff)+' odpis již zaplaceného majetku. Poplatky se nevrací, rezervovaní lidé se uvolní.',()=>cancelOpening6(id,q),'Ukončit a vyúčtovat');}catch(e){toast(e.message);}};
 on('[data-goto]',b=>{el('modal').close();goto(b.dataset.goto);});
}
cityView=function(){let html=OPENING_UI6.cityView();for(const p of state.opening6.projects.filter(p=>p.kind==='cafe'&&p.status==='active'&&!p.entity))html=html.replace(new RegExp('<button[^>]*data-open="'+p.location+'"[^>]*>[^<]*</button>'),`<button class="soft wide" data-opening-report6="${p.id}">Probíhá příprava · ${OPENING_PHASES6[p.phase]}</button>`).replace(new RegExp('<button[^>]*data-franchise="'+p.location+'"[^>]*>[^<]*</button>'),'');return openingCards6('cafe')+html;};
storesView=function(){return openingCards6('cafe')+OPENING_UI6.storesView();};
roastersView=function(){return openingCards6('roaster')+OPENING_UI6.roastersView();};
bakeryView=function(){return openingCards6('bakery')+OPENING_UI6.bakeryView();};
map=function(){let html=OPENING_UI6.map();for(const p of state.opening6.projects.filter(p=>p.kind==='cafe'&&p.status==='active'&&!p.entity))html=html.replace(new RegExp('(<button[^>]*data-location="'+p.location+'"[^>]*>)[^<]*(</button>)'),'$1◷$2');return html;};
openDialog=function(id,franchise=false){const l=loc(id),existing=openingReserved6(id);if(existing)return openingProjectDialog6(existing.id);const first=state.bootstrap6?.cashOnly&&!state.stores.length&&!state.opening6.projects.some(p=>p.status==='active'),defaultDesign=first?'starter':'base',defaultSpace=first?'starter':'existing';show(`<span class="eyelabel">${esc(l.city)} · PŘÍPRAVA NOVÉHO PROVOZU</span><h2>${esc(l.name)}</h2><p>Prostor → instalace → skutečný tým → zkušební provoz. Před spuštěním kavárna neprodává.</p><div class="fields">${field('Značka',`<select id="openBrand">${brandOptions(state.brands[0].id)}</select>`)}${field('Receptura kávy',`<select id="openBlend">${blendOptions(state.blends[0].id)}</select>`)}${field('Návrh vybavení',`<select id="openDesign5">${option('starter','Startovací kavárna · 16 míst',defaultDesign)+option('base','Základní kavárna · 24 míst',defaultDesign)+state.studio5.designs.map(d=>option(d.id,d.name,defaultDesign)).join('')}</select>`)}${field('Prostor',`<select id="openSpace5">${Object.entries(PREMISES_SPACES5).map(([k,c])=>option(k,c.name,defaultSpace)).join('')}</select>`)}${field('Smlouva',`<select id="openTenure5">${propertyChoices5('legacy')+option('owned','Koupit budovu','legacy')}</select>`)}${field('Tým na ráno / poledne / večer',`<select id="openingShift6"><option value="lean">Malý začátek · 1 / 1 / 1</option><option value="full">Plný tým podle místní špičky</option></select>`)}${field('Vedoucí přípravy',`<select id="openingManager6">${option('','Vede zakladatel · bez další mzdy','')+state.talents.filter(p=>!academyBusy6(p.pid)).map(p=>option(p.pid,p.name+' · '+MANAGER_STRATEGIES6[CHARACTER_TYPES6[p.character6.trait].strategy].name+' · '+money(p.salary)+'/týden','')).join('')}</select>`)}</div><div id="openingPreview5"></div><button class="primary wide" id="openConfirm">Zahájit placenou přípravu</button>`);
 let q;const read=()=>({location:id,franchise,brand:el('openBrand').value,blend:el('openBlend').value,design:el('openDesign5').value,options:{space:el('openSpace5').value,kind:el('openTenure5').value},managerPid:el('openingManager6').value||null,shifts:el('openingShift6').value==='lean'?[1,1,1]:makeStore(id).daily.shifts}),preview=()=>{try{q=openingQuote6('cafe',read());const funding=openingFunding6(q);el('openingPreview5').innerHTML=rows([['Platba nyní · prostor, vybavení a příprava',money(q.cost)],['Hotovost po zahájení',money(state.cash-q.cost)],['Plán bez zdržení',q.totalWeeks+' týdnů · do T'+(state.week+q.totalWeeks-1)],['Držení prostoru / týden',money(q.holdingRent)],['Fixní provoz po otevření · bez kávy a surovin',q.running===null?'Platí partner':money(q.running)],['Rezervovaní skuteční pracovníci',q.staffPids.map(id=>state.baristaCandidates.find(p=>p.pid===id).name).join(', ')||'Franšízový partner'],['Pozdější nábor · platba',money(q.staffPids.length*crewFee5())]])+(funding?`<section class="opening-budget6 ${funding.safe?'ready':'attention'}"><h3>Rozpočet až po otevření</h3>${rows([['Příprava · nájem, mzdy a odvody',money(funding.holding)],['Dodavatel a dvě dodávky po 25 kg',money(funding.coffee)],['Zkouška · bez započtení budoucích tržeb',money(funding.trial)],['Rezerva na 3 týdny fixního provozu',money(funding.reserve)],['Celkem potřebuješ včetně investice a náboru',money(funding.required)],['Chybějící financování',money(funding.shortfall)]])}<p class="sub">${funding.safe?'Rozpočet pokrývá přípravu i první provoz.':'Tato varianta by spotřebovala provozní rezervu. Zmenši prostor a vybavení, veď přípravu sám nebo zvol levnější adresu.'} Káva počítá se Sousedskou pražírnou. Jde o odhad bez tržeb a mimořádných událostí, nikoli platbu ani záruku zisku.</p></section>`:'')+'<p class="sub">Mzdy začnou při náboru, vedoucí se platí od zahájení. Receptura určuje nabídku, ale nevytváří zásoby. Po zahájení sjednej dodavatele; káva se objedná po instalaci. Bez zaplacené kávy se spuštění zdrží. Kompaktní vybavení bez placené kontroly prodlouží zkoušku o týden. Menší tým omezuje kapacitu obsluhy.</p>';const detailed=el('openingPreview5').innerHTML;el('openingPreview5').innerHTML=`<div class="ux-open-summary11"><div><small>Zaplatíš při zahájení</small><strong>${money(q.cost)}</strong></div><div><small>Plán přípravy</small><strong>${q.totalWeeks} týdnů</strong></div><div><small>Rozpočet až po otevření${funding?' · včetně rezervy':''}</small><strong>${funding?money(funding.required):money(q.cost)}</strong></div><div><small>K dispozici</small><strong>${money(state.cash)}</strong></div><p class="${funding&&!funding.safe||state.cash<q.cost?'attention':''}">${funding&&!funding.safe||state.cash<q.cost?'Chybí '+money(Math.max(funding?.shortfall||0,q.cost-state.cash))+'. Zmenši prostor nebo vybavení.':'Příprava je v rozpočtu. Po zahájení ještě sjednej skutečné dodávky kávy.'}</p></div><details><summary>Podrobný rozpočet, tým a podmínky</summary>${detailed}</details>`;el('openConfirm').disabled=state.cash<q.cost||state.over||first&&funding&&!funding.safe;}catch(e){q=null;el('openingPreview5').textContent=e.message;el('openConfirm').disabled=true;}};
 for(const key of ['openBrand','openBlend','openDesign5','openSpace5','openTenure5','openingShift6','openingManager6'])el(key).onchange=preview;el('openDesign5').onchange=()=>{if(el('openDesign5').value==='starter')el('openSpace5').value='starter';else if(el('openSpace5').value==='starter')el('openSpace5').value='existing';preview();};preview();el('openConfirm').onclick=()=>{try{if(!q)throw Error('Vyber platnou přípravu.');if(first&&!franchise&&!openingFunding6(q).safe)throw Error('Na první kavárnu potřebuješ i rozpočet přípravy a provozní rezervu.');const p=startOpening6('cafe',read(),q);persist();render();openingProjectDialog6(p.id);toast('Příprava zahájena. Sjednej dodávky kávy.');}catch(e){toast(e.message);}};
};
bind=function(){OPENING_UI6.bind();on('[data-opening-report6]',b=>openingProjectDialog6(b.dataset.openingReport6));on('[data-bakery-buy5]',b=>{try{const data={type:b.dataset.bakeryBuy5,city:el('bakeryCity5').value},q=openingQuote6('bakery',data);confirmAction('Připravit vlastní pekárnu?',money(q.cost)+' nyní; plán '+q.totalWeeks+' týdnů. '+q.staffPids.length+' skutečných pekařů, další nábor '+money(q.staffPids.length*8000)+', placené držení místa a mzdy. Zkouška má polovinu fyzické kapacity.',()=>startOpening6('bakery',data,q),'Zahájit přípravu');}catch(e){toast(e.message);}});};
render=function(){OPENING_UI6.render();el('next').disabled=state.over||!state.stores.length&&!hasOpeningWork6();};
help=function(){OPENING_UI6.help();const p=document.createElement('p');p.textContent='Nová kavárna, pražírna i pekárna vzniká postupně. Zaplacený prostor a vybavení je rozestavěný majetek; držení místa, správní poplatky, nábor a mzdy jsou další skutečné náklady. Vedoucí s povahou průkopníka a provozní dovedností alespoň 75 může při povolení instalaci urychlit. Kvalitář v limitu a rezervě zaplatí kontrolu 1 800 Kč; kompaktní vybavení pak nezpůsobí dodatečný týden zkoušky. Šetřílek nepřidává nepovolené investice. Přehled přípravy ukazuje plán, zásahy a skutečné termíny.';el('modalContent').append(p);};el('help').onclick=help;render();

const OPENING_CREW_VIEW6=crewView;
crewView=function(){const projects=state.opening6.projects.filter(p=>p.kind==='cafe'&&!p.franchise&&p.status==='active'&&!p.entity);return (projects.length?`<section class="card opening-crew6"><h2>Týmy připravovaných kaváren</h2>${projects.map(p=>`<article><h3>${esc(p.name)}</h3><p>${p.hired?'Tým přijatý':'Tým rezervovaný'} · ${p.people.map(x=>esc(x.name)).join(', ')||'Bez pracovníků'}</p><p class="sub">${p.blueprint.shifts.join(' / ')} lidí na ráno / poledne / večer · ${OPENING_PHASES6[p.phase]}</p><button class="soft" data-opening-team6="${p.id}">Tým a směny přípravy</button></article>`).join('')}</section>`:'')+(projects.length&&!state.stores.some(s=>!s.franchise)?'':OPENING_CREW_VIEW6());};
const OPENING_TEAM_BIND6=bind;
bind=function(){OPENING_TEAM_BIND6();on('[data-opening-team6]',b=>openingTeamDialog6(b.dataset.openingTeam6));};

const OPENING_DIGEST_DESTINATION6=digestDestination6;
digestDestination6=function(x){if(x.key.startsWith('opening-')&&openingById6(x.target)){closeDigest6();openingProjectDialog6(x.target);return;}OPENING_DIGEST_DESTINATION6(x);};
